// The TV app's Expo config (ADR 0059): one app for Apple TV and, in 4.5c, Android TV, generated by
// `expo prebuild` with react-native-tvos and its config plugin, which retargets the native project
// to tvOS (https://docs.expo.dev/guides/building-for-tv/). ios/ is never committed.
import { cpSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
import type { ExpoConfig } from 'expo/config'
import { type ConfigPlugin, withDangerousMod, withXcodeProject } from 'expo/config-plugins'
import { withReactNativeDir } from '../../packages/native/plugins/index.ts'
import pkg from './package.json'

const brand = '../../packages/brand/assets/icons'
const TV_ICONS = 'App Icon & Top Shelf Image'

/**
 * The brand's own Apple TV catalog (the layered icon at both sizes, the App Store icon and both top
 * shelf images) copied into the asset catalog whole and named as the app icon, as Xcode's tvOS
 * template does (https://developer.apple.com/design/human-interface-guidelines/app-icons#tvOS).
 * config-tv's appleTVImages wants each layer under a distinct file name, which the catalog doesn't
 * have, so it isn't used.
 */
const withAppleTVIcons: ConfigPlugin = (config) => {
  config = withDangerousMod(config, [
    'ios',
    (c) => {
      const catalog = join(
        c.modRequest.platformProjectRoot,
        c.modRequest.projectName ?? '',
        'Images.xcassets',
      )
      mkdirSync(catalog, { recursive: true })
      cpSync(
        join(c.modRequest.projectRoot, brand, 'tvos', `${TV_ICONS}.brandassets`),
        join(catalog, `${TV_ICONS}.brandassets`),
        {
          recursive: true,
        },
      )
      return c
    },
  ])
  return withXcodeProject(config, (c) => {
    const configurations = c.modResults.pbxXCBuildConfigurationSection()
    for (const entry of Object.values(configurations)) {
      const settings = (entry as { buildSettings?: Record<string, string> }).buildSettings
      if (settings?.PRODUCT_NAME === undefined) continue
      settings.ASSETCATALOG_COMPILER_APPICON_NAME = `"${TV_ICONS}"`
      settings.ASSETCATALOG_COMPILER_INCLUDE_ALL_APPICON_ASSETS = 'YES'
    }
    return c
  })
}

const config: ExpoConfig = {
  name: 'highsea',
  slug: 'highsea-tv',
  version: pkg.version,
  // highsea://connect (connectivity.md)
  scheme: 'highsea',
  userInterfaceStyle: 'dark',
  backgroundColor: '#0b0b0c',
  ios: {
    bundleIdentifier: 'tv.highsea.tv',
    infoPlist: {
      // tvOS never asks for the local network, but browsing still declares the type (Apple TN3179)
      NSBonjourServices: ['_highsea._tcp'],
      // servers at home answer over plain HTTP by their LAN address or .local name
      // (https://developer.apple.com/documentation/bundleresources/information-property-list/nsapptransportsecurity/nsallowslocalnetworking)
      NSAppTransportSecurity: { NSAllowsLocalNetworking: true },
      ITSAppUsesNonExemptEncryption: false,
    },
  },
  plugins: [
    ['@react-native-tvos/config-tv', { isTV: true, tvosDeploymentTarget: '16.4' }],
    'expo-router',
    'expo-secure-store',
    [
      'expo-font',
      {
        fonts: [
          '../../packages/brand/fonts/Geist-Regular.ttf',
          '../../packages/brand/fonts/Geist-Medium.ttf',
          '../../packages/brand/fonts/Geist-SemiBold.ttf',
          '../../packages/brand/fonts/GeistMono-Regular.ttf',
          '../../packages/brand/fonts/GeistMono-Medium.ttf',
        ],
      },
    ],
    'expo-video',
    [
      'expo-splash-screen',
      { image: `${brand}/splash/mark.png`, imageWidth: 160, backgroundColor: '#0b0b0c' },
    ],
  ],
}

// plugins written here are applied directly, since ExpoConfig's `plugins` lists names only
// (https://docs.expo.dev/config-plugins/plugins/#apply-a-plugin)
export default withAppleTVIcons(withReactNativeDir(config))
